\section{Discussion and open problems}\label{sec:disc}

\subsection{What the augmentation theorem buys, and what it does not}

The theorem is a purely structural mechanism converting any antichain into exactly one unit
of forbidden dimension, with no counting, no symmetry and no assumption on the family. That
generality is its strength for monotonicity questions and its weakness for the asymptotic
constant: it is insensitive to the sizes of the objects involved, whereas the
$(3+\varepsilon)$ problem for $B_3$ is entirely about sizes. The two ends of the subject meet
in Remark~\ref{rem:gain}, where the structural mechanism does deliver a quantitative gain,
off by $\Theta(\sqrt{n})$ from the conjectured truth.

\subsection{Conjectures}

\begin{conjecture}[Subadditivity of the free dimension]\label{conj:F1}
If $\FF$ is weak $B_d$-free and $\GG$ is weak $B_e$-free, then $\FF \cup \GG$ is weak
$B_{d+e}$-free; likewise for strong freeness. Equivalently: for every $A \subseteq B_{d+e}$
containing no weak copy of $B_e$, there is an order embedding
$B_d \hookrightarrow B_{d+e}$ whose image avoids $A$.
\end{conjecture}

The case $e=1$ is Theorem~\ref{thm:augweak}, antichains being exactly the weak $B_1$-free
families; exhaustive verification on small ground sets has produced no counterexample. The
naive strategy---lift along an up-set---must be replaced by an $e$-step staircase.

\begin{conjecture}[The $\varepsilon$-gain for $B_3$]
There exist $\varepsilon > 0$ and $n_0$ such that for all $n \ge n_0$ there is a weak
$B_3$-free family $\FF \subseteq 2^{[n]}$ with $|\FF| \ge (3+\varepsilon)\central$, and
likewise a strong $B_3$-free family of that size.
\end{conjecture}

It is falsified by any proof of $\La(n,B_3) \le 3\central + o(\central)$. What the present
framework contributes is a list of what such a construction cannot be: it cannot be obtained
by adding sets to a layer family, nor be a level family or any permutation-invariant family.

\begin{conjecture}[Sharpening the general upper bound]
The factor $2^{d}-1$ in $\La(n,B_d) \le (2^{d}-1)\central$ can be replaced by $d+c$ for an
absolute constant $c$; concretely $\La(n,B_3) \le 4\central$ for all $n$.
\end{conjecture}

\begin{conjecture}[Quantitative monotonicity]
$\La(n,B_{d+1}) - \La(n,B_d) \ge \central$ for $n \ge d+1$.
\end{conjecture}

The qualitative part is Theorem~\ref{thm:strict}; Corollary~\ref{cor:gain} gives the gain up
to a factor $\Theta(\sqrt{n})$; the analogous statement restricted to level families is a
theorem, the level optima differing by exactly one central binomial coefficient.

\begin{conjecture}[Weak versus strong]
For every $d \ge 2$ there is $n_0$ with $\La(n,B_d) < \La^{*}(n,B_d)$ for all $n \ge n_0$.
\end{conjecture}

Any such $n_0$ exceeds $d+1$: the two parameters agree at $n = d$ and $n = d+1$, agree for
all $n$ when $d = 1$, agree on level families for all $n$ and $d$, and---by
Section~\ref{sec:comp}---agree for all $n \le 4$.

\begin{conjecture}[Stability]
There is an absolute $c > 0$ such that for all $\varepsilon > 0$ and all large $n$, every
weak $B_3$-free family $\FF \subseteq 2^{[n]}$ with $|\FF| \ge (3+\varepsilon)\central$
satisfies $\min_{S} |\FF \mathbin{\triangle} \LL(S)| \ge c\,\varepsilon\central$, the
minimum over all sets $S$ of levels; more generally with $\LL(S)$ replaced by any
permutation-invariant family.
\end{conjecture}

\begin{question}
For which $t$ is the maximum size of a weak $B_d$-free family contained in $d+t$ consecutive
layers equal to the sum of the $d$ largest of those binomial coefficients? Since the known
$\varepsilon$-constructions for $B_d$, $d \ge 4$, appear to live on boundedly many layers, we
expect the general bounded-width guess to be false.
\end{question}

\subsection{Further directions}

\begin{enumerate}
\item \textbf{Improve the pigeonhole.} Lemma~\ref{lem:bigantichain} spends a factor $n+1$ by
treating all layers alike. Replacing the largest layer of the complement by a maximum
antichain of the complement---computable in polynomial time via Dilworth's theorem and a
flow argument---should recover part of the $\sqrt{n}$ loss.
\item \textbf{Iterate the augmentation with structure.} Any decomposition of a family into
$k$ antichains certifies weak $B_k$-freeness, and by Mirsky's theorem the least such $k$ is
the height, so Theorem~\ref{thm:height} is exactly the antichain-decomposition criterion.
Whether decomposition into families that are weak $B_{e_i}$-free certifies
$B_{\sum e_i}$-freeness is Conjecture~\ref{conj:F1}.
\item \textbf{Push the exhaustive frontier.} Determining $\La(5,B_2)$ and $\La(5,B_3)$ would
be the first test of the weak-versus-strong conjecture outside the range of known
equalities. The $2^{32}$ families demand branch-and-bound over downward-closed freeness,
seeded by layer families and by Theorem~\ref{thm:pigeon} as a lower-bound certificate.
\end{enumerate}

\section{Summary of results}

\begin{itemize}
\item \textbf{Lifting Lemma.} For each up-set $U$ of $B_d$, adjoining the new atom exactly on
$U$ defines an order embedding $B_d \hookrightarrow B_{d+1}$.
\item \textbf{Avoidance.} For every antichain $A \subseteq B_{d+1}$ there is an order
embedding $B_d \hookrightarrow B_{d+1}$ whose image misses $A$.
\item \textbf{Antichain Augmentation Theorem.} A weak (strong) $B_d$-free family united with
an antichain is weak (strong) $B_{d+1}$-free.
\item \textbf{Strict monotonicity.} $\La(n,B_d) < \La(n,B_{d+1})$ and
$\La^{*}(n,B_d) < \La^{*}(n,B_{d+1})$ for all $n \ge d$; strictness holds precisely when
$d \le n$; and $\La(n,B_d)+k \le \La(n,B_{d+k})$ for $d+k \le n+1$.
\item \textbf{Quantitative form.} $2^{n} + n\,\La(n,B_d) \le (n+1)\,\La(n,B_{d+1})$ for all
$n,d$, giving a gain of order $\central/\sqrt{n}$ for fixed $d$.
\item \textbf{Height criteria.} No chain of $d+1$ sets $\Rightarrow$ weak $B_d$-free
$\Rightarrow$ no chain of $2^{d}$ sets; at most $d$ distinct sizes $\Rightarrow$ weak
$B_d$-free; both height thresholds are attained.
\end{itemize}

\end{document}

