"""Antichain-Avoiding Lift: an order embedding B_d -> B_(d+1) missing a prescribed antichain.

Subsets of a d-element set are encoded as bitmasks; B_d is the set of masks 0 .. 2^d - 1,
and B_(d+1) adds the new atom `star` with bit value 2^d.
"""

from __future__ import annotations

from typing import Dict, Iterable, List, Set


def subset(a: int, b: int) -> bool:
    """True iff the set encoded by `a` is contained in the set encoded by `b`."""
    return a & ~b == 0


def generated_up_set(d: int, seeds: Iterable[int]) -> Set[int]:
    """The smallest up-set of B_d containing every mask in `seeds`."""
    seed_list: List[int] = [z for z in seeds if z < (1 << d)]
    return {x for x in range(1 << d) if any(subset(z, x) for z in seed_list)}


def lift_along_up_set(d: int, up_set: Set[int]) -> Dict[int, int]:
    """The map lambda_U : B_d -> B_(d+1) adjoining the new atom exactly on `up_set`.

    It is an order embedding for every up-set U: X is contained in Y if and only if
    lambda_U(X) is contained in lambda_U(Y).
    """
    star = 1 << d
    return {x: (x | star if x in up_set else x) for x in range(1 << d)}


def embedding_avoiding_antichain(d: int, antichain: Set[int]) -> Dict[int, int]:
    """An order embedding B_d -> B_(d+1) whose image is disjoint from `antichain`.

    `antichain` is a set of masks of B_(d+1), no one contained in another.  Complexity:
    O(4^d) to build the up-set, O(2^d) to build the map.
    """
    seeds = {z for z in range(1 << d) if z in antichain}
    return lift_along_up_set(d, generated_up_set(d, seeds))


def verify(d: int, antichain: Set[int], phi: Dict[int, int]) -> bool:
    """Check injectivity, the two-sided order condition, and avoidance of the antichain."""
    values = list(phi.values())
    if len(set(values)) != len(values):
        return False
    for x in range(1 << d):
        for y in range(1 << d):
            if subset(x, y) != subset(phi[x], phi[y]):
                return False
    return not (set(values) & set(antichain))


if __name__ == "__main__":
    import itertools
    for d in range(0, 5):
        universe = list(range(1 << (d + 1)))
        for level in range(d + 2):
            antichain = {m for m in universe if bin(m).count("1") == level}
            for size in range(len(antichain) + 1):
                for sub_ac in itertools.islice(itertools.combinations(sorted(antichain), size), 20):
                    A = set(sub_ac)
                    phi = embedding_avoiding_antichain(d, A)
                    assert verify(d, A, phi), (d, A)
        print(f"d = {d}: every tested antichain of B_{d+1} is dodged by a copy of B_{d}.")

"""Exhaustive Determination of the Extremal Numbers La(n, B_d) and La*(n, B_d).

Weak (and strong) B_d-freeness is a downward-closed property of families: every subfamily
of a free family is free.  Hence scanning candidate families in order of decreasing size and
returning the first free one found yields the exact extremal number together with an
extremal witness.

Copy detection is a backtracking search over the 2^d vertices of B_d, taken in an order of
increasing rank so that every constraint linking a newly placed vertex to an earlier one can
be tested at once.  Worst-case cost is O(|F|^(2^d)) but the inclusion constraints prune
almost everything; the search returns immediately when |F| < 2^d.

Complexity of the outer loop is O(2^(2^n)) family inspections in the worst case, which keeps
the method to n <= 4 in practice; the descending scan usually terminates after examining a
few thousand families.
"""

from __future__ import annotations

from itertools import combinations
from typing import Iterable, List, Optional, Sequence, Tuple


def popcount(x: int) -> int:
    return bin(x).count("1")


def strict_subset(a: int, b: int) -> bool:
    return a != b and a & ~b == 0


def boolean_lattice(d: int) -> List[int]:
    """The vertices of B_d listed by increasing rank (a linear extension)."""
    return sorted(range(1 << d), key=lambda m: (popcount(m), m))


def contains_copy(family: Iterable[int], d: int, strong: bool = False) -> bool:
    """Does `family` contain a weak (or strong) copy of B_d?"""
    sets: List[int] = sorted(set(family), key=lambda m: (popcount(m), m))
    elems = boolean_lattice(d)
    if len(sets) < len(elems):
        return False
    assign: List[Optional[int]] = [None] * len(elems)

    def compatible(i: int, value: int) -> bool:
        for j in range(i):
            other = assign[j]
            assert other is not None
            if other == value:
                return False
            p, q = elems[j], elems[i]
            if strict_subset(p, q):
                if not strict_subset(other, value):
                    return False
            elif strong and strict_subset(other, value):
                return False
            if strict_subset(q, p):
                if not strict_subset(value, other):
                    return False
            elif strong and strict_subset(value, other):
                return False
        return True

    def backtrack(i: int) -> bool:
        if i == len(elems):
            return True
        for value in sets:
            if compatible(i, value):
                assign[i] = value
                if backtrack(i + 1):
                    return True
                assign[i] = None
        return False

    return backtrack(0)


def extremal_number(n: int, d: int, strong: bool = False) -> Tuple[int, Tuple[int, ...]]:
    """Return (La(n, B_d), witness) — or the strong analogue when `strong` is set."""
    ground: Sequence[int] = range(1 << n)
    for size in range(1 << n, -1, -1):
        for candidate in combinations(ground, size):
            if not contains_copy(candidate, d, strong):
                return size, candidate
    raise RuntimeError("unreachable")


if __name__ == "__main__":
    print(" n  d   La(n,B_d)  La*(n,B_d)")
    for n in range(5):
        for d in range(1, 6):
            weak, _ = extremal_number(n, d, strong=False)
            strong, _ = extremal_number(n, d, strong=True)
            print(f" {n}  {d}      {weak:4d}        {strong:4d}")

