"""Visualization: the lifting construction inside a cube.

Draws the Hasse diagram of the Boolean lattice B_3 (all subsets of {1, 2, *}) three times,
for three different antichain obstacles A, and in each case highlights the copy of B_2
produced by the lifting construction: take the bottom face {X : * not in X} and push the
up-set U generated by the obstacle's bottom-face members up to the top face.

The pictures make visible the single reason the construction works: an image vertex that
has been pushed up strictly contains a member of A, and an antichain contains nothing
strictly above one of its own members.
"""

from __future__ import annotations

from typing import Dict, List, Set, Tuple

import matplotlib.pyplot as plt

D = 2                      # we embed B_2 into B_3
STAR = 1 << D              # the new atom


def popcount(x: int) -> int:
    return bin(x).count("1")


def subset(a: int, b: int) -> bool:
    return a & ~b == 0


def label(mask: int) -> str:
    names = {0: "1", 1: "2", 2: "*"}
    items = [names[i] for i in range(D + 1) if mask >> i & 1]
    return "{" + ",".join(items) + "}" if items else "\u2205"


def up_set(obstacle: Set[int]) -> Set[int]:
    """U = { X in B_D : some Z contained in X has its bottom-face copy in A }."""
    return {X for X in range(1 << D)
            if any(subset(Z, X) and Z in obstacle for Z in range(1 << D))}


def lift(X: int, U: Set[int]) -> int:
    return X | STAR if X in U else X


def positions() -> Dict[int, Tuple[float, float]]:
    levels: List[List[int]] = [[] for _ in range(D + 2)]
    for m in range(1 << (D + 1)):
        levels[popcount(m)].append(m)
    pos: Dict[int, Tuple[float, float]] = {}
    for k, row in enumerate(levels):
        for i, m in enumerate(row):
            pos[m] = ((i + 1) / (len(row) + 1), k)
    return pos


def draw(ax, obstacle: Set[int], title: str) -> None:
    pos = positions()
    U = up_set(obstacle)
    image = {lift(X, U) for X in range(1 << D)}

    for m in range(1 << (D + 1)):
        for i in range(D + 1):
            if not (m >> i & 1):
                q = m | (1 << i)
                both = m in image and q in image
                ax.plot([pos[m][0], pos[q][0]], [pos[m][1], pos[q][1]],
                        color="#059669" if both else "#cbd5e1",
                        lw=2.4 if both else 1.0, zorder=1)

    for m in range(1 << (D + 1)):
        x, y = pos[m]
        in_obstacle = m in obstacle
        pushed = m in image and bool(m & STAR)
        color = "#ef4444" if in_obstacle else "#fbbf24" if pushed else \
                "#34d399" if m in image else "#e2e8f0"
        ax.scatter([x], [y], s=980, color=color, edgecolors="#0f172a", zorder=2, linewidths=1.2)
        ax.text(x, y, label(m), ha="center", va="center", fontsize=8.5, zorder=3,
                color="#0f172a")

    ax.set_title(title, fontsize=10)
    ax.set_xlim(-0.05, 1.05)
    ax.set_ylim(-0.6, D + 1.6)
    ax.axis("off")


def main() -> None:
    scenarios = [
        (set(), "empty obstacle:\nthe plain bottom face already works"),
        ({0b01}, "obstacle A = {{1}}:\nthe up-set above {1} is pushed to the top face"),
        ({0b01, 0b10}, "obstacle A = {{1}, {2}}:\nonly the empty set stays on the bottom face"),
    ]
    fig, axes = plt.subplots(1, len(scenarios), figsize=(13.5, 4.6))
    for ax, (obstacle, title) in zip(axes, scenarios):
        draw(ax, obstacle, title)
    fig.suptitle("Lifting a copy of $B_2$ inside $B_3$ so as to avoid an antichain "
                 "(red = obstacle, green = image, amber = image pushed up)", fontsize=11)
    fig.tight_layout()
    fig.savefig("lifting_construction.png", dpi=160)
    print("wrote lifting_construction.png")


if __name__ == "__main__":
    main()
